const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),z=require('node:zlib'),E=require('../place-evidence.js'),P=require('../place-photos.js'),C=require('../place-conditions.js');const dir='docs/nationwide-expansion-20261020d/',load=n=>JSON.parse(z.gunzipSync(fs.readFileSync(dir+n+'.json.gz'))),m=load('manifest'),photos=load('selected-photos'),source=load('source-evidence');
test('eight additional places retain source identity, original licensed files and individually bounded permission',()=>{assert.equal(m.facilities.length,8);assert.equal(photos.length,8);assert.equal(m.courses.length,0);for(const row of m.facilities){const p=photos.find(p=>p.id===row.id),s=source.find(p=>p.row.id===row.id);assert.equal(row.name,s.tour.title.trim());assert.equal(row.lat,Number(s.tour.yCoord));assert.equal(row.lng,Number(s.tour.xCoord));assert(['Type1','Type3'].includes(p.officialImage.cpyrhtDivCd));assert.equal(p.officialImage.originimgurl.replace(/^http:/,'https:'),p.photo.original);assert.equal(P.get(row).src,p.photo.src);require('./helpers/photo-original.cjs')(p.photo);assert.equal(E.conditions({...row,description:'changed'}),null);assert.equal(E.intro({...row,address:'other branch'}),null);if(s.pet)assert.deepEqual(E.conditions(row),s.pet);else assert.equal(E.get(row).introAllowance.wholeAreaConfirmed,false);const html=fs.readFileSync('places/'+row.id+'/index.html','utf8');assert(html.includes(P.url(p.photo)));assert(html.includes('반려견 동반 조건'));}
 const coffee=m.facilities.find(x=>x.name==='소디스커피');assert(C.get(coffee).find(r=>r.label==='견종·크기 조건').value.includes('10㎏ 미만'));assert(C.get(coffee).find(r=>r.label==='필수 준비물').value.includes('배변봉투'));const outlet=m.facilities.find(x=>x.name==='아이즈빌아울렛');assert(C.get(outlet)[0].value.includes('일부구역'));assert(C.get(outlet)[0].value.includes('개별 문의'));const sol=m.facilities.find(x=>x.name==='솔바람캠핑장');assert(sol.address.startsWith('충청남도 서천군'));assert(C.get(sol)[1].value.includes('대형견'));assert(C.get(sol)[2].value.includes('입마개'));
});
test('specific outlet restrictions replace an empty broad code while original photos, description and other information remain intact',()=>{const [p]=load('existing-condition-proof'),r=E.get(p.row);assert.equal(r.petContentId,p.sourceTour.contentId);assert.equal(r.contentId,p.before.contentId);assert.equal(r.name,p.sourceTour.title);assert.deepEqual(r.pet,p.sourcePet);assert.equal(r.pet.acmpyTypeCd,'일부구역 동반가능');assert(C.get(p.row)[0].value.includes('식음료 매장은 동반 불가'));assert(C.get(p.row)[1].value.includes('20kg 이하'));assert.equal(r.description,p.before.description);assert.deepEqual(r.photo,{...p.before.photo,place:r.name+' 공식 관광자료 제공 사진',date:'',datasetContentId:p.before.contentId});assert.deepEqual(r.gallery,p.before.gallery);for(const key of Object.keys(p.before).filter(k=>!['contentId','source','pet','petChecked','photo'].includes(k)))assert.deepEqual(r[key],p.before[key],key);assert.equal(E.conditions({...p.row,address:'different outlet'}),null);});
